# Custom verifier: compute expected lookup-derived values and compare direct evaluated formulas conceptually.
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path,data_only=False)
data=wb['Data']; task=wb['Task']
# Build lookup from actual data table
headers=[data.cell(4,c).value for c in range(8,13)]
rows={data.cell(r,4).value:{headers[i]: data.cell(r,8+i).value for i in range(5)} for r in range(21,39)}
errors=[]
# Formula shape and lookup expected values
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        code=task.cell(r,4).value
        for c in range(8,13):
            col=get_column_letter(c); year=task.cell(10,c).value
            formula=task.cell(r,c).value
            expected_formula=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
            if formula != expected_formula:
                errors.append((f'{col}{r}', formula, expected_formula))
            if code not in rows or year not in rows[code]:
                errors.append((f'{col}{r}', 'lookup missing', code, year))
# Net/stat/weighted formula shapes
for i in range(6):
    for c in range(8,13):
        col=get_column_letter(c); r=35+i
        expected=f'=({col}{12+i}-{col}{19+i})/{col}{26+i}*100'
        if task.cell(r,c).value != expected:
            errors.append((f'{col}{r}', task.cell(r,c).value, expected))
for c in range(8,13):
    col=get_column_letter(c)
    expected_map={42:f'=MIN({col}35:{col}40)',43:f'=MAX({col}35:{col}40)',44:f'=MEDIAN({col}35:{col}40)',45:f'=AVERAGE({col}35:{col}40)',46:f'=PERCENTILE({col}35:{col}40,0.25)',47:f'=PERCENTILE({col}35:{col}40,0.75)',50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'}
    for r,expected in expected_map.items():
        if task.cell(r,c).value != expected:
            errors.append((f'{col}{r}', task.cell(r,c).value, expected))
print('custom_formula_check_errors:', len(errors))
if errors:
    for e in errors[:20]: print(e)
else:
    print('custom_formula_check_passed')
print('sample expected numeric outputs:')
for c in range(8,13):
    col=get_column_letter(c); year=task.cell(10,c).value
    flows=[]; weights=[]
    for i in range(6):
        adm=rows[task.cell(12+i,4).value][year]
        dis=rows[task.cell(19+i,4).value][year]
        cap=rows[task.cell(26+i,4).value][year]
        flows.append((adm-dis)/cap*100); weights.append(cap)
    wmean=sum(f*w for f,w in zip(flows,weights))/sum(weights)
    print(col, year, 'H35:L40 style first/last flow=', flows[0], flows[-1], 'weighted=', wmean)
PY
